/* ::::: dialog header ::::: */

#am-main-title {
  padding-block-end: 8px;

  & > button {
    min-inline-size: unset;
  }
}

.dialogheader-title {
  overflow: hidden;
  align-self: center;
  margin-inline-start: 0;
  font-size: 1.46em;
  font-weight: 300;
  line-height: 1.3em;
  color: var(--color-text-base);

  &::before {
    overflow: hidden;
    text-overflow: ellipsis;
  }
}
